const blocks = $input.all().map((item) => item.json);
let text = "I have put my company url for context about my brand. Make the video about the following informatiion for a blog post I wrote: ";

blocks.forEach((block) => {
  if (block.content) {
    text += block.content + "\n";
  }
  if (block.image?.file?.url) {
    text += block.image.file.url + "\n";
  }
});

return [{ json: { text }, pairedItem: blocks.map((_, index) => index) }];
